    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= 90 and opp.get('budget', 0) >= 120:
                    rich_aggressive += 1

    winners_est = max(1, int(supply // WATER_REQ))
    num_alive = len(alive_opps) + 1

    if not alive_opps:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 40.0))
        return float(min(budget, 18.0))

    high_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    pressure = 0
    if winners_est < min(2, num_alive):
        pressure += 2
    elif winners_est == 2 and num_alive > 2:
        pressure += 1
    if high_prev >= 120:
        pressure += 2
    elif high_prev >= 80:
        pressure += 1
    if desperate_count >= winners_est:
        pressure += 1

    if urgency >= 5:
        bid = max(95.0, high_prev + 3.0, avg_prev + 8.0)
    elif urgency >= 3:
        bid = max(62.0, min(98.0, high_prev * 0.78 + 6.0))
    else:
        if winners_est >= 2:
            bid = 24.0 + 4.0 * pressure
            if rich_aggressive >= 2:
                bid = min(bid, 30.0)
        else:
            bid = 34.0 + 8.0 * pressure
            if high_prev >= 100 and hp > 4 and no_water_days == 0:
                bid = 22.0

    remaining_days = max(1, 10 - int(day) + 1)
    soft_cap = budget / remaining_days + DAILY_SALARY * 0.45
    if urgency <= 1:
        bid = min(bid, soft_cap)

    if hp > 6 and no_water_days == 0 and rich_aggressive >= 2 and winners_est >= 2:
        bid = min(bid, 26.0)

    if hp <= 3 and budget >= 80:
        bid = max(bid, 78.0)

    bid = max(0.0, min(float(bid), float(budget)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Gather previous bids from traces
    prev_bids = []
    for oid, opp in alive_opponents.items():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev:
            prev_bids.append(prev['bid'])

    # Determine a baseline bid
    if no_water_days > 0 or hp <= 3:
        # Need water urgently
        base_bid = DAILY_SALARY * 0.85
    elif supply >= 20:
        base_bid = DAILY_SALARY * 0.65
    elif supply >= 15:
        base_bid = DAILY_SALARY * 0.75
    else:
        base_bid = DAILY_SALARY * 0.8

    # Adjust based on opponents' previous aggressiveness
    if prev_bids:
        max_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        # If they were very aggressive, they might be low on budget now
        if max_prev > DAILY_SALARY * 0.85:
            bid = min(base_bid, DAILY_SALARY * 0.75)
        else:
            # Try to outbid the average by a small margin
            bid = max(base_bid, avg_prev + 1.5)
    else:
        bid = base_bid

    # Ensure bid is within budget and not excessive
    bid = min(bid, budget)
    bid = max(bid, 0.1)
    return bid
